  function comparison() {
    const first = sum();
    if (!['<', '<=', '>', '>=', '==', '!='].includes(current().value)) return first;
    const operands = [first];
    const operators = [];
    while (['<', '<=', '>', '>=', '==', '!='].includes(current().value)) {
      operators.push(take());
      operands.push(sum());
    }
    return { type: 'comparison', operands, operators };
  }

  function sum() {
    let left = product();
    while (is('+') || is('-')) {
      const operator = take();
      left = binary(operator, left, product());
    }
    return left;
  }

  function product() {
    let left = unary();
    while (['*', '/', '//', '%'].includes(current().value)) {
      const operator = take();
      left = binary(operator, left, unary());
    }
    return left;
  }

  /** Signs are collected iteratively, so a long sign run does not recurse. */
  function unary() {
    const signs = [];
    while (is('+') || is('-')) signs.push(take());
    let node = power();
    for (let index = signs.length - 1; index >= 0; index -= 1) {
      node = { type: 'unary', operator: signs[index], operand: node };
    }
    return node;
  }

  function power() {
    const left = primary();
    if (!is('**')) return left;
    const operator = take();
    return binary(operator, left, unary());
  }

  function primary() {
    const token = take();
    if (token.type === 'number') return { type: 'number', value: token.value };
    if (token.type === 'identifier') {
      if (!is('(')) return { type: 'variable', name: token.value, column: token.column };
